function findProductsOfElements(queries) {
  const BITS = 50;

  // How many integers in 1..n have this bit set.
  function countWithBit(n, bit) {
    const half = 2 ** bit;
    const fullBlocks = Math.floor((n + 1) / (2 * half));
    return fullBlocks * half + Math.max(0, ((n + 1) % (2 * half)) - half);
  }

  // counts[bit] = how many of the first k elements of big_nums equal 2^bit.
  function powerCounts(k) {
    let low = 0;
    let high = k;
    while (low < high) {
      const mid = Math.ceil((low + high) / 2);
      let used = 0;
      for (let bit = 0; bit < BITS && used <= k; bit++) {
        used += countWithBit(mid, bit);
      }
      if (used <= k) {
        low = mid;
      } else {
        high = mid - 1;
      }
    }
    const counts = [];
    let used = 0;
    for (let bit = 0; bit < BITS; bit++) {
      counts.push(countWithBit(low, bit));
      used += counts[bit];
    }
    const next = low + 1;
    for (let bit = 0; used < k; bit++) {
      if (Math.floor(next / 2 ** bit) % 2 === 1) {
        counts[bit]++;
        used++;
      }
    }
    return counts;
  }

  function powMod(base, exponent, mod) {
    let result = 1 % mod;
    base %= mod;
    while (exponent > 0) {
      if (exponent % 2 === 1) result = (result * base) % mod;
      base = (base * base) % mod;
      exponent = Math.floor(exponent / 2);
    }
    return result;
  }

  const answer = [];
  for (const [from, to, mod] of queries) {
    const upper = powerCounts(to + 1);
    const lower = powerCounts(from);
    let product = 1 % mod;
    for (let bit = 0; bit < BITS; bit++) {
      const factor = powMod(2 ** bit, upper[bit] - lower[bit], mod);
      product = (product * factor) % mod;
    }
    answer.push(product);
  }
  return answer;
}

