function findProductsOfElements(queries) {
  // A different method with BigInt: fix the bits of the number where the first k elements end, from the top bit down.
  // A block of 2^j numbers sharing higher bits (with ones set bits whose exponents add to bitsSum) holds
  // 2^j * ones + j * 2^(j-1) elements whose exponents add to 2^j * bitsSum + 2^(j-1) * j(j-1)/2.
  const exponentPrefix = (k) => {
    let remaining = BigInt(k);
    let ones = 0n, bitsSum = 0n, total = 0n, number = 0n;
    for (let j = 50n; j >= 0n; j--) {
      const size = 1n << j;
      const half = j > 0n ? size / 2n : 0n;
      const count = size * ones + j * half;
      const sum = size * bitsSum + half * (j * (j - 1n) / 2n);
      if (count <= remaining) {
        remaining -= count;
        total += sum;
        number += size;
        ones++;
        bitsSum += j;
      }
    }
    // The rest are the smallest powers of the number that is cut off.
    for (let j = 0n; remaining > 0n; j++) {
      if ((number >> j) & 1n) {
        total += j;
        remaining--;
      }
    }
    return total;
  };
  const powerOfTwo = (exponent, mod) => {
    let result = 1n % mod;
    let base = 2n % mod;
    for (; exponent > 0n; exponent >>= 1n) {
      if (exponent & 1n) result = (result * base) % mod;
      base = (base * base) % mod;
    }
    return result;
  };
  return queries.map(([from, to, mod]) => Number(powerOfTwo(exponentPrefix(to + 1) - exponentPrefix(from), BigInt(mod))));
}

