function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1e15;
  // A value in [0, 10^15] with random low digits too.
  const huge = () => Math.min(LIMIT, int(0, 1e9) * 1e6 + int(0, 999999));
  const pickMod = () => {
    const r = rand();
    if (r < 0.15) return int(1, 2);
    if (r < 0.3) return 2 ** int(1, 16);
    if (r < 0.65) return int(3, 60);
    return int(1, 100000);
  };
  const queries = [];
  if (size === 'small') {
    const count = int(1, 5);
    for (let i = 0; i < count; i++) {
      const from = int(0, 80);
      const to = rand() < 0.2 ? from : from + int(0, 60);
      queries.push([from, to, pickMod()]);
    }
    return [queries];
  }
  for (let i = 0; i < 500; i++) {
    const r = rand();
    let from, to;
    if (r < 0.3) {
      from = huge();
      to = Math.min(LIMIT, from + int(0, 1000));
    } else if (r < 0.4) {
      from = int(0, 1000);
      to = LIMIT - int(0, 1000);
    } else {
      const a = huge();
      const b = huge();
      from = Math.min(a, b);
      to = Math.max(a, b);
    }
    queries.push([from, to, pickMod()]);
  }
  return [queries];
}
